(window.DETAIL_C = window.DETAIL_C || {})["mth-11-05"] = {"mth-11-05-g01":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Total outcomes: {1, 2, 3, 4, 5, 6}, so n(S) = 6.","Numbers greater than 4: {5, 6}, so n(E) = 2.","P(E) = n(E) / n(S) = 2/6 = 1/3."],"others":"2/3 counts four favourable outcomes, not two. 1/2 would be three outcomes. 1/6 is only one outcome.","trap":"Greater than 4 does not include 4 itself.","answer":"1/3"},"mth-11-05-g02":{"idea":"When two events can happen together, subtract the overlap in the addition theorem.","steps":["Let A = king (4 cards) and B = heart (13 cards).","The king of hearts is in both, so P[A and B] = 1/52.","P[A or B] = P[A] + P[B] − P[A and B] = 4/52 + 13/52 − 1/52.","= 16/52 = 4/13."],"others":"17/52 forgets to subtract the king of hearts, so it is counted twice. 13/52 counts hearts only. 1/13 counts kings only.","trap":"Forgetting the overlap gives 17/52.","answer":"4/13"},"mth-11-05-g03":{"idea":"Bayes' theorem finds the chance of the cause after we see the result.","steps":["P[A] = P[B] = 1/2. Red balls: P[R|A] = 3/5 and P[R|B] = 2/6 = 1/3.","P[A|R] = P[A]P[R|A] / [P[A]P[R|A] + P[B]P[R|B]].","Numerator = 0.5 × 0.6 = 0.3.","Denominator = 0.3 + 0.5 × 0.3333 = 0.46667.","P[A|R] = 0.3 / 0.46667 = 0.6429."],"trap":"Do not mix up P[R|A] with P[A|R]. Make a small table of the two bags first.","answer":"0.6429"},"mth-11-05-b01":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["A pack has 52 cards, and 13 are spades.","P(spade) = 13/52 = 1/4."],"others":"1/2 is the chance of a red card or of a black card. 1/13 is the chance of one given rank. 1/26 is the chance of one given red or black suit rank pair.","trap":"One suit is one quarter of the pack.","answer":"1/4"},"mth-11-05-b02":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Sample space: {HH, HT, TH, TT}, so n(S) = 4.","Exactly one head: {HT, TH}, so n(E) = 2.","P = 2/4 = 1/2."],"others":"3/4 is the chance of at least one head. 1/3 wrongly treats the outcomes as three. 1/4 is the chance of just one of HH or TT.","trap":"HT and TH are different outcomes.","answer":"1/2"},"mth-11-05-b03":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Total balls = 5 + 3 = 8.","Red balls = 5.","P(red) = 5/8."],"others":"3/8 is the chance of blue. 5/3 is more than 1, which no probability can be. 1/8 is the chance of one particular ball.","trap":"A probability is never above 1.","answer":"5/8"},"mth-11-05-b04":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Total outcomes: 6.","Even numbers: {2, 4, 6}, which is 3 outcomes.","P = 3/6 = 1/2."],"others":"2/3 counts four outcomes. 1/6 counts only one. 1/3 counts only two.","answer":"1/2"},"mth-11-05-b05":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Each suit has 3 face cards: jack, queen and king.","Four suits give 3 × 4 = 12 face cards.","P = 12/52 = 3/13."],"others":"1/13 counts one face card per suit pair. 3/26 would be six face cards. 4/13 would include the aces or a fourth face rank.","trap":"Aces are not face cards here.","answer":"3/13"},"mth-11-05-b06":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Total outcomes with two dice: 6 × 6 = 36.","Sum 7: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1), which is 6 outcomes.","P = 6/36 = 1/6."],"others":"1/36 is one pair only. 7/36 uses 7 instead of the count of pairs. 1/12 counts only three pairs.","trap":"(1,6) and (6,1) are different outcomes.","answer":"1/6"},"mth-11-05-b07":{"idea":"Independent events multiply.","steps":["One coin shows a head with probability 1/2.","The three coins are independent.","P(all heads) = (1/2)³ = 1/8."],"others":"1/4 is for two coins. 1/2 is for one coin. 3/8 is the chance of exactly one or exactly two heads, not all three.","trap":"Total outcomes for 3 coins: 2³ = 8.","answer":"1/8"},"mth-11-05-b08":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["APPLE has 5 letters.","The letter P appears 2 times.","P(P) = 2/5."],"others":"1/2 and 3/5 do not match the count of P letters. 1/5 would be the chance of a letter that appears once.","trap":"Count repeated letters each time.","answer":"2/5"},"mth-11-05-b09":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Multiples of 4 from 1 to 20: {4, 8, 12, 16, 20}, which is 5 numbers.","Total numbers = 20.","P = 5/20 = 1/4."],"others":"1/20 is one number. 3/10 would be six numbers. 1/5 would be four numbers, missing 20.","trap":"Do not forget 20.","answer":"1/4"},"mth-11-05-b10":{"idea":"An event and its complement together have probability 1.","steps":["P[not A] = 1 − P[A].","= 1 − 0.3 = 0.7."],"others":"1.3 is more than 1. 0.3 is P[A] itself. 0 would mean A is certain.","trap":"P[A] + P[not A] = 1.","answer":"0.7"},"mth-11-05-b11":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Total outcomes: 6.","Primes on a die: {2, 3, 5}, which is 3 outcomes.","P = 3/6 = 1/2."],"others":"1/3 counts only two primes. 1/6 counts only one. 2/3 counts four numbers.","trap":"1 is not a prime number.","answer":"1/2"},"mth-11-05-b12":{"idea":"Independent stages multiply the number of outcomes.","steps":["Each toss has 2 outcomes.","Two tosses give 2 × 2 = 4 outcomes.","They are {HH, HT, TH, TT}."],"others":"8 is the count for three tosses. 2 is for one toss. 6 does not match any power of 2.","trap":"n tosses give 2ⁿ outcomes.","answer":"4"},"mth-11-05-b13":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["There are 2 red kings: hearts and diamonds.","Total cards = 52.","P = 2/52 = 0.0385."],"trap":"Check: P(red) × P(king | red) = (26/52)(2/26) = 2/52.","answer":"0.0385"},"mth-11-05-b14":{"idea":"Independent events multiply.","steps":["Each roll shows a 6 with probability 1/6.","The rolls are independent.","P = (1/6)(1/6) = 1/36 = 0.0278."],"trap":"Total outcomes of two rolls: 36, with one favourable.","answer":"0.0278"},"mth-11-05-b15":{"idea":"The addition theorem avoids counting the overlap twice.","steps":["P(M or S) = P(M) + P(S) − P(M and S).","= 0.5 + 0.4 − 0.2.","Result: 0.7."],"others":"0.9 forgets to subtract the overlap. 0.6 and 0.1 are not the result of the addition theorem with these values.","trap":"Adding without subtracting gives 0.9.","answer":"0.7"},"mth-11-05-b16":{"idea":"For mutually exclusive events, add the probabilities.","steps":["Getting a 2 and getting a 5 cannot happen together.","P(2 or 5) = 1/6 + 1/6.","= 2/6 = 1/3."],"others":"1/6 is the chance of just one number. 1/2 is three numbers. 2/3 is four numbers.","answer":"1/3"},"mth-11-05-b17":{"idea":"Given information shrinks the sample space.","steps":["The number is even, so the outcomes are {2, 4, 6}.","Each is equally likely.","Only one of the three is 4.","P(4 | even) = 1/3."],"others":"1/2 and 2/3 are not one in three. 1/6 uses all six outcomes and ignores the information.","trap":"Use 3 outcomes, not 6.","answer":"1/3"},"mth-11-05-b18":{"idea":"For independent events, multiply the probabilities.","steps":["P[A and B] = P[A] × P[B].","= 0.6 × 0.5 = 0.3."],"others":"1.1 is the sum, and a probability cannot be above 1. 0.06 is a slip in the decimal point. 0.5 is just P[B].","trap":"Independent: multiply. Exclusive: add.","answer":"0.3"},"mth-11-05-b19":{"idea":"Mutually exclusive events have no outcome in common.","steps":["Even: {2, 4, 6}. Odd: {1, 3, 5}.","They share no outcome.","So they are mutually exclusive."],"others":"Less than 4 and greater than 2 share 3. Even and multiple of 3 share 6. Prime and even share 2.","trap":"Look for one common outcome.","answer":"\"number is even\" and \"number is odd\""},"mth-11-05-b20":{"idea":"Odds in favour are P[A] to P[not A].","steps":["P[A] = 2/5, so P[not A] = 3/5.","Odds in favour = (2/5) : (3/5).","= 2 : 3."],"others":"3 : 2 reverses the order and is the odds against. 2 : 5 compares A with the total. 5 : 2 is not related to these values.","trap":"Odds are favourable to unfavourable, not to total.","answer":"2 : 3"},"mth-11-05-b21":{"idea":"Without replacement, the second chance changes.","steps":["P(1st white) = 4/10.","Then 3 white remain among 9 balls: 3/9.","P(both) = (4/10)(3/9) = 12/90 = 2/15."],"others":"4/15 and 1/3 and 1/5 do not come from reducing the second draw to 3 of 9.","trap":"Check: C(4,2)/C(10,2) = 6/45 = 2/15.","answer":"2/15"},"mth-11-05-b22":{"idea":"Events are independent if P[A and B] = P[A] × P[B].","steps":["P[A] = 13/52 = 1/4 and P[B] = 12/52 = 3/13.","Product = 3/52.","A and B overlap in 3 cards: J, Q, K of hearts, so P[A and B] = 3/52.","The two are equal, so A and B are independent."],"others":"Not independent would need the product to differ from 3/52, but it does not. Hearts and face cards do overlap. The answer can be determined.","answer":"Yes -- P(A) x P(B) = P(A and B)"},"mth-11-05-b23":{"idea":"Use the complement for 'at least one'.","steps":["P(at least one head) = 1 − P(no heads).","No heads means TT, with probability 1/4.","1 − 1/4 = 3/4."],"others":"1/2 is exactly one head. 1/4 is no head. 1 would mean it is certain.","trap":"At least one = 1 − none.","answer":"3/4"},"mth-11-05-b24":{"idea":"Count choices with combinations.","steps":["Ways to choose 2 boys from 3: C(3,2) = 3.","Ways to choose any 2 from 5: C(5,2) = 10.","P = 3/10."],"others":"1/2, 3/5 and 2/5 do not come from 3 over 10.","trap":"Check: (3/5)(2/4) = 3/10.","answer":"3/10"},"mth-11-05-b25":{"idea":"Exhaustive events together cover every outcome.","steps":["Every roll is even or odd.","So these two events cover all 6 outcomes."],"others":"Prime and even miss 1. Less than 3 and greater than 5 miss 3 and 4. Just 1 and just 2 miss many outcomes.","trap":"Exhaustive = nothing is left out.","answer":"\"number is even\" and \"number is odd\""},"mth-11-05-b26":{"idea":"For mutually exclusive events, P[A and B] = 0.","steps":["P[A or B] = P[A] + P[B] − P[A and B].","P[A and B] = 0.","= 0.3 + 0.4 = 0.7."],"others":"1 would need the sum to be 1. 0.1 is the difference. 0.12 is the product, used for independent events.","trap":"Exclusive is not the same as independent.","answer":"0.7"},"mth-11-05-b27":{"idea":"Find the common outcomes of the two sets.","steps":["A = {1, 2, 3, 4, 5}. B = {2, 4, 6, 8, 10}.","Common outcomes: {2, 4}.","P[A and B] = 2/10 = 1/5."],"others":"1/2 is P[A] or P[B]. 2/5 would be four common outcomes. 3/10 would be three.","answer":"1/5"},"mth-11-05-b28":{"idea":"Mutually exclusive sums can be added.","steps":["P(sum 7) = 6/36.","P(sum 11) = 2/36, from (5,6) and (6,5).","P(7 or 11) = 6/36 + 2/36 = 8/36 = 2/9."],"others":"1/6 is only a sum of 7. 7/36 and 1/9 do not match the 8 favourable pairs.","trap":"Total pairs: 36.","answer":"2/9"},"mth-11-05-b29":{"idea":"Use the complement.","steps":["P(diamond) = 13/52 = 1/4.","P(not diamond) = 1 − 1/4 = 3/4.","Check: 39 of 52 cards are not diamonds."],"others":"1/4 is the chance of a diamond. 1/13 is one rank. 12/13 is not related to the suit count.","answer":"3/4"},"mth-11-05-b30":{"idea":"Complements of independent events are also independent.","steps":["P[not C] = 2/3 and P[not D] = 3/4.","P(neither) = (2/3)(3/4).","= 6/12 = 1/2."],"others":"5/12, 1/6 and 7/12 do not come from multiplying the two complements.","trap":"Check: P[C or D] = 1/3 + 1/4 − 1/12 = 1/2, so P(neither) = 1/2.","answer":"1/2"},"mth-11-05-b31":{"idea":"Use inclusion and exclusion for 'or'.","steps":["Multiples of 3 up to 30: 10.","Multiples of 5: 6.","Multiples of both (of 15): 2.","Count = 10 + 6 − 2 = 14.","P = 14/30 = 7/15."],"others":"2/5 and 1/2 ignore the exact counts. 8/15 forgets to subtract the common multiples enough, giving 16.","trap":"Forgetting the overlap gives 16/30 = 8/15.","answer":"7/15"},"mth-11-05-b32":{"idea":"For independent events, P[A or B] = P[A] + P[B] − P[A]P[B].","steps":["0.7 = 0.4 + P[B] − 0.4 P[B].","0.7 = 0.4 + 0.6 P[B].","0.3 = 0.6 P[B], so P[B] = 0.5."],"others":"0.7 is P[A or B] itself. 0.3 is only the difference. 0.6 does not satisfy the equation.","trap":"Check: 0.4 + 0.5 − 0.2 = 0.7.","answer":"0.5"},"mth-11-05-b33":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Total outcomes of 3 tosses = 8.","At least two heads: HHH, HHT, HTH, THH, which is 4 outcomes.","P = 4/8 = 1/2."],"others":"5/8 counts five outcomes. 1/4 counts two. 3/8 counts only exactly two heads.","trap":"At least two includes three.","answer":"1/2"},"mth-11-05-b34":{"idea":"A sum is even when both dice are even or both are odd.","steps":["P(both even) = (3/6)(3/6) = 1/4.","P(both odd) = (3/6)(3/6) = 1/4.","Total = 1/4 + 1/4 = 1/2."],"others":"5/12, 1/3 and 2/3 do not match 18 favourable pairs out of 36.","trap":"18 of 36 pairs have an even sum.","answer":"1/2"},"mth-11-05-b35":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Total balls = 12.","Green balls = 4.","P(green) = 4/12 = 1/3 = 0.3333."],"trap":"Check: 1 − 3/12 − 5/12 = 4/12.","answer":"0.3333"},"mth-11-05-b36":{"idea":"Use the complement for 'at least one'.","steps":["P(at least one tail) = 1 − P(no tails).","No tails means HH, probability 1/4.","= 1 − 0.25 = 0.75."],"trap":"Check: outcomes HT, TH, TT give 3/4.","answer":"0.75"},"mth-11-05-b37":{"idea":"Use the addition theorem for ace or spade.","steps":["Aces: 4. Spades: 13. Ace of spades is in both: 1.","Count = 4 + 13 − 1 = 16.","P = 16/52 = 0.3077."],"trap":"Check: 52 − 16 = 36 cards are neither, and 1 − 36/52 = 16/52.","answer":"0.3077"},"mth-11-05-b38":{"idea":"Count favourable groups with combinations.","steps":["Choose 2 women of 3: C(3,2) = 3.","Choose 1 man of 4: C(4,1) = 4.","Favourable = 3 × 4 = 12.","Total = C(7,3) = 35.","P = 12/35 = 0.3429."],"trap":"Check: exactly 2 women plus 1 man makes 3 people.","answer":"0.3429"},"mth-11-05-b39":{"idea":"Conditional probability: P[A|B] = P[A and B] / P[B].","steps":["P[A and B] = 0.2 and P[B] = 0.35.","P[A|B] = 0.2 / 0.35.","So the answer is 4/7."],"others":"2/5 is 0.2 / 0.5, which divides by P[A]. 7/20 is P[B] over a different total. 5/7 is a slip in the numerator.","trap":"Divide by the given event, B.","answer":"4/7"},"mth-11-05-b40":{"idea":"Find the outcomes that satisfy both conditions.","steps":["Both dice show the same number d, so the sum is 2d.","2d = 8 gives d = 4.","Only (4,4) works.","P = 1/36."],"others":"1/6, 1/12 and 1/18 would need 6, 3 or 2 pairs, but only one pair works.","answer":"1/36"},"mth-11-05-b41":{"idea":"Without replacement, the second chance changes.","steps":["P(1st is a king) = 4/52.","Removing a king leaves 51 cards, still with 4 queens.","P(2nd is a queen) = 4/51.","P = (4/52)(4/51) = 16/2652 = 4/663."],"others":"1/169 is for replacement, 4/52 times 4/52. 1/13 and 4/51 are single steps.","trap":"The second denominator is 51.","answer":"4/663"},"mth-11-05-b42":{"idea":"Exactly one trait means X only or Y only.","steps":["P(X only) = 0.3 × (1 − 0.4) = 0.18.","P(Y only) = 0.4 × (1 − 0.3) = 0.28.","Total = 0.18 + 0.28 = 0.46."],"others":"0.7 is the sum, which counts both traits twice. 0.58 is P(X or Y), which includes both traits. 0.12 is P(both).","trap":"Check: P(X or Y) − P(both) = 0.58 − 0.12 = 0.46.","answer":"0.46"},"mth-11-05-b43":{"idea":"Use the complement for 'at least one'.","steps":["P(no defective) = (15/20)(14/19) = 210/380 = 21/38.","P(at least one) = 1 − 21/38 = 17/38."],"others":"21/38 is the chance of none. 5/19 and 1/4 do not follow from the two steps.","trap":"Check: (75 + 10)/190 = 17/38.","answer":"17/38"},"mth-11-05-b44":{"idea":"Odds against are P[not A] to P[A].","steps":["P[not A] : P[A] = 3 : 2.","So P[A] = 2 / (3 + 2) = 2/5."],"others":"3/2 is above 1. 2/3 uses the odds as if the total were 3. 3/5 is P[not A].","trap":"Odds against put the 'no' side first.","answer":"2/5"},"mth-11-05-b45":{"idea":"Without replacement, each draw has a smaller pack.","steps":["P = (13/52)(12/51)(11/50).","= 1716/132600.","= 0.0129."],"trap":"Check: C(13,3)/C(52,3) = 286/22100.","answer":"0.0129"},"mth-11-05-b46":{"idea":"Probability = favourable outcomes / total equally likely outcomes.","steps":["Total outcomes = 36.","Pairs differing by 2: (1,3), (3,1), (2,4), (4,2), (3,5), (5,3), (4,6), (6,4).","That is 8 outcomes.","P = 8/36 = 0.2222."],"trap":"Count both orders of each pair.","answer":"0.2222"},"mth-11-05-b47":{"idea":"Use inclusion and exclusion for 'or'.","steps":["French or German = 18 + 15 − 6 = 27.","P = 27/40 = 0.675."],"trap":"Check: French only 12 + German only 9 + both 6 = 27.","answer":"0.675"}};
